import { writeFileSync } from "node:fs";
import { pages, platforms } from "./pages.ts";

const platform = platforms.find((name) => name === process.argv[2]);
if (!platform) throw new Error(`Usage: node scripts/catalog.ts <${platforms.join("|")}>`);

const catalog = pages(platform).map(({ id }) => ({
  id: JSON.stringify(id),
  label: JSON.stringify(`page:${id}`),
  name: id.split(/[-_]/).map((word) => word[0]!.toUpperCase() + word.slice(1)).join(""),
}));

writeFileSync(new URL("../src/App.weft", import.meta.url), [
  "// Generated by scripts/catalog.ts from pages.json.",
  ...catalog.map(({ name }) => `import "./pages/${name}.weft"`),
  "",
  "component Showcase() {",
  '    state page = ""',
  "",
  '    if (page == "") {',
  "        Scroll {",
  "            Column(padding = 16, gap = 8) {",
  ...catalog.map(({ id, label }) => `                Button(onClick = { page = ${id} }) { Text(${label}) }`),
  "            }",
  "        }",
  "    }",
  ...catalog.map(({ id, name }) => `    if (page == ${id}) { ${name}() }`),
  "}",
  "",
].join("\n"));
